// ─── File: StatelessSessionDemo.java ───
// Runnable demo: one login token recognized by every service on any instance.
package com.bank.statelesssession;

import java.util.logging.*;

public class StatelessSessionDemo {

    private static final Logger log = Logger.getLogger("Stateless");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        TokenIssuer issuer = new TokenIssuer("nbin-key", 300_000);  // 5-min token
        LoadBalancer lb = new LoadBalancer();

        // Login ONCE → self-contained token (the "session").
        String token = issuer.issue("rajesh", "CUSTOMER");
        log.info("Rajesh logged in once; token carries identity (no server session)");

        // Hop across services; LB routes each call to a RANDOM instance; all recognize him.
        lb.route(new AccountService(issuer)).handle(token, "SAV2001");
        lb.route(new TransferService(issuer)).handle(token, "to CUR3001 Rs.50000");
        lb.route(new StatementService(issuer)).handle(token, "last 30 days");

        // Short-lived token model: after expiry the same token is rejected everywhere.
        String shortToken = issuer.issue("rajesh", "CUSTOMER", 50);  // 50ms
        Thread.sleep(80);
        try { new AccountService(issuer).handle(shortToken, "SAV2001"); }
        catch (SecurityException e) {
            log.warning("expired token rejected → client uses refresh token to get a new one");
        }
    }
}

// ─── token/TokenIssuer.java (mint + validate; the single trust anchor) ───
class TokenIssuer {
    private final String key; private final long defaultExpiryMs;
    TokenIssuer(String key, long expiryMs) { this.key = key; this.defaultExpiryMs = expiryMs; }
    String issue(String user, String role) { return issue(user, role, defaultExpiryMs); }
    String issue(String user, String role, long expiryMs) {
        long exp = System.currentTimeMillis() + expiryMs;
        String payload = user + "|" + role + "|" + exp;
        return payload + "." + sign(payload);
    }
    private String sign(String p) { return Integer.toHexString((p + key).hashCode()); }
    // Each service calls validate() LOCALLY — no shared session lookup.
    String[] validate(String token) {
        int dot = token.lastIndexOf('.');
        String payload = token.substring(0, dot), sig = token.substring(dot + 1);
        if (!sign(payload).equals(sig)) throw new SecurityException("bad signature");
        String[] parts = payload.split("\\|");
        if (System.currentTimeMillis() > Long.parseLong(parts[2]))
            throw new SecurityException("token expired");
        return new String[]{parts[0], parts[1]};   // [user, role]
    }
}

// ─── service/AccountService.java (validates token locally) ───
class AccountService {
    private static final Logger log = Logger.getLogger("Stateless");
    private final TokenIssuer issuer;
    AccountService(TokenIssuer issuer) { this.issuer = issuer; }
    void handle(String token, String arg) {
        String[] id = issuer.validate(token);     // local validation, no session store
        log.info(() -> "[AccountService inst-" + inst() + "] " + id[0]
                + " (" + id[1] + ") viewed " + arg);
    }
    private int inst() { return 1 + (int)(Math.random() * 3); }
}

