// ─── infra/LoadBalancer.java (routes to an arbitrary instance — stateless lets this work) ───
class LoadBalancer {
    <T> T route(T serviceInstance) { return serviceInstance; }  // any instance can serve any request
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
